        * If true then an error diagnostic is reported.
        * If false then there is no error and a new ɵprov property is not added.
        */
-      private errorOnDuplicateProv = true) {}
+      private errorOnDuplicateProv = true) {
+    // Prevent infinite recursion by tracking processed classes
+    this.injectableRegistry = new class extends InjectableClassRegistry {
+      private processedClasses = new Set<string>();
+      
+      registerInjectable(type: ts.TypeReferenceNode, meta: InjectableHandlerData): void {
+        const className = type.getText();
+        if (this.processedClasses.has(className)) {
+          // Skip if already processed to prevent recursion
+          return;
+        }
+        this.processedClasses.add(className);
+        super.registerInjectable(type, meta);
+      }
+    }();
+  }

